+    // Preserve the branded picker in browsers without customizable selects.
+    if (!CSS.supports('appearance', 'base-select')) {
+      const select = document.querySelector('#coffee-roast');
+      const container = select.parentElement;
+      const trigger = document.createElement('button');
+      const value = document.createElement('span');
+      const arrow = document.createElement('span');
+      const list = document.createElement('ul');
+      select.id = 'coffee-roast-native';
+      select.hidden = true;
+      trigger.type = 'button';
+      trigger.id = 'coffee-roast';
+      trigger.className = 'roast-trigger';
+      trigger.setAttribute('aria-haspopup', 'listbox');
+      trigger.setAttribute('aria-expanded', 'false');
+      trigger.setAttribute('aria-controls', 'roast-options');
+      trigger.setAttribute('aria-labelledby', 'roast-label roast-value');
+      value.id = 'roast-value';
+      value.textContent = select.selectedOptions[0].textContent;
+      arrow.textContent = '▾';
+      arrow.setAttribute('aria-hidden', 'true');
+      trigger.append(value, arrow);
+      list.id = 'roast-options';
+      list.className = 'roast-options';
+      list.hidden = true;
+      list.setAttribute('role', 'listbox');
+      list.setAttribute('aria-labelledby', 'roast-label');
+
+      const close = (restoreFocus = false) => {
+        list.hidden = true;
+        trigger.setAttribute('aria-expanded', 'false');
+        if (restoreFocus) trigger.focus();
+      };
+      const items = Array.from(select.options, (option, index) => {
+        const item = document.createElement('li');
+        item.textContent = option.textContent;
+        item.tabIndex = -1;
+        item.setAttribute('role', 'option');
+        item.setAttribute('aria-selected', String(option.selected));
+        item.addEventListener('click', () => {
+          select.selectedIndex = index;
+          value.textContent = option.textContent;
+          items.forEach((entry, i) => entry.setAttribute('aria-selected', String(i === index)));
+          select.dispatchEvent(new Event('change', { bubbles: true }));
+          close(true);
+        });
+        list.append(item);
+        return item;
+      });
+      const open = () => {
+        list.hidden = false;
+        trigger.setAttribute('aria-expanded', 'true');
+        items[select.selectedIndex].focus();
+      };
+      trigger.addEventListener('click', () => list.hidden ? open() : close());
+      trigger.addEventListener('keydown', (event) => {
+        if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
+          event.preventDefault();
+          open();
+        }
+      });
+      list.addEventListener('keydown', (event) => {
+        const index = items.indexOf(document.activeElement);
+        let next;
+        if (event.key === 'ArrowDown') next = (index + 1) % items.length;
+        else if (event.key === 'ArrowUp') next = (index - 1 + items.length) % items.length;
+        else if (event.key === 'Home') next = 0;
+        else if (event.key === 'End') next = items.length - 1;
+        else if (event.key === 'Escape') close(true);
+        else if (event.key === 'Tab') { close(true); return; }
+        else if (event.key === 'Enter' || event.key === ' ') items[index].click();
+        else if (event.key.length === 1) {
+          const match = items.findIndex(item => item.textContent.toLowerCase().startsWith(event.key.toLowerCase()));
+          if (match !== -1) next = match;
+        } else return;
+        event.preventDefault();
+        if (next !== undefined) items[next].focus();
+      });
+      document.addEventListener('click', (event) => {
+        if (!container.contains(event.target)) close();
+      });
+      container.addEventListener('focusout', (event) => {
+        if (!container.contains(event.relatedTarget)) close();
+      });
+      container.append(trigger, list);
+    }
