+/* Declare precedence once; keep all rules inside their owning layer. */
+@layer reset, tokens, base, layout, components;
+
+@layer reset {
+  :where(*, *::before, *::after) {
+    box-sizing: border-box;
+    margin: 0;
+    padding: 0;
+  }
+}
+
+@layer tokens {
+  :root {
+    --color-primary: #4e342e;
+    --color-secondary: #d7ccc8;
+    --color-accent: #ffab40;
+    --color-text: #3e2723;
+    --color-page: #fafafa;
+    --color-surface: #fff;
+    --color-on-primary: #fff;
+    --color-hero-overlay: rgb(0 0 0 / 50%);
+
+    --font-family-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    --font-size-small: 0.85rem;
+    --font-size-nav: 0.9rem;
+    --font-size-logo: 1.5rem;
+    --font-size-hero: 3rem;
+    --font-weight-bold: 700;
+    --line-height-body: 1.6;
+    --letter-spacing-logo: 1px;
+
+    --space-1: 0.3125rem;
+    --space-2: 0.625rem;
+    --space-3: 0.75rem;
+    --space-4: 0.9375rem;
+    --space-5: 1rem;
+    --space-6: 1.25rem;
+    --space-7: 2.5rem;
+    --page-gutter: 5%;
+
+    --radius-small: 0.25rem;
+    --radius-button: 0.3125rem;
+    --radius-card: 0.5rem;
+    --border-width: 1px;
+    --shadow-card: 0 2px 5px rgb(0 0 0 / 10%);
+    --duration-interaction: 0.3s;
+    --layer-sticky: 1000;
+    --content-max: 68.75rem;
+    --card-min: 15.625rem;
+    --hero-size: 60vh;
+    --image-hero: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  }
+}
+
+@layer base {
+  body {
+    font-family: var(--font-family-body);
+    line-height: var(--line-height-body);
+    color: var(--color-text);
+    background-color: var(--color-page);
+  }
+
+  :where(nav a, .btn, .footer-links a) {
+    text-decoration: none;
+  }
+}
+
+@layer layout {
+  .container {
+    max-inline-size: var(--content-max);
+    margin-block: var(--space-7);
+    margin-inline: auto;
+    padding-inline: var(--space-6);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(var(--card-min), 1fr));
+    gap: var(--space-6);
+    margin-block-start: var(--space-6);
+  }
+}
+
+@layer components {
+  :where(nav, .hero) {
+    display: flex;
+    align-items: center;
+    color: var(--color-on-primary);
+  }
+
+  :where(.hero, .section-title, .card, footer) {
+    text-align: center;
+  }
+
+  :where(nav, .btn) {
+    background-color: var(--color-primary);
+  }
+
+  :where(nav a, .btn) {
+    color: var(--color-on-primary);
+  }
+
+  nav {
+    position: sticky;
+    inset-block-start: 0;
+    z-index: var(--layer-sticky);
+    justify-content: space-between;
+    padding-block: var(--space-5);
+    padding-inline: var(--page-gutter);
+  }
+
+  .logo {
+    font-size: var(--font-size-logo);
+    font-weight: var(--font-weight-bold);
+    letter-spacing: var(--letter-spacing-logo);
+  }
+
+  nav :where(ul) {
+    display: flex;
+    gap: var(--space-6);
+    padding-inline-start: var(--space-6);
+    list-style: none;
+  }
+
+  nav :where(a) {
+    font-size: var(--font-size-nav);
+    transition: color var(--duration-interaction);
+  }
+
+  nav :where(a:is(:hover, :focus-visible)) {
+    color: var(--color-accent);
