+    transition: background-color var(--duration-interaction);
+  }
+
+  .btn:is(:hover, :focus-visible) {
+    background-color: var(--color-text);
+  }
+
+  footer {
+    background-color: var(--color-secondary);
+    padding-block: var(--space-7);
