index 0000000..67b2a93
--- /dev/null
+++ b/js/signatures.mjs
@@ -0,0 +1,50 @@
+const encoder = new TextEncoder();
+export const DOMAIN = 'daily-grind:document:v1';
+export const suites = ['ML-DSA-65', 'Ed25519', 'ECDSA'];
+export const bytesToBase64 = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes)));
+export function fromBase64(value) {
+  if (typeof value !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(value) || value.length > 20000) throw new Error('Invalid signature encoding.');
+  return Uint8Array.from(atob(value), c => c.charCodeAt(0));
+}
+export function algorithm(suite) {
+  if (!suites.includes(suite)) throw new Error('Unsupported signing algorithm.');
+  return suite === 'ECDSA' ? { name: 'ECDSA', hash: 'SHA-256' } : suite;
