+export async function generateSigner() {
+  if (!globalThis.crypto?.subtle) throw new Error('Signing requires HTTPS or localhost and a browser with Web Crypto support.');
+  const candidates = [];
+  if (globalThis.SubtleCrypto?.supports?.('sign', 'ML-DSA-65')) candidates.push('ML-DSA-65');
+  candidates.push('Ed25519', 'ECDSA');
+  for (const suite of candidates) {
+    try {
+      const keys = await crypto.subtle.generateKey(suite === 'ECDSA' ? { name: suite, namedCurve: 'P-256' } : suite, false, ['sign', 'verify']);
+      const publicKey = bytesToBase64(await crypto.subtle.exportKey('spki', keys.publicKey));
+      return { suite, keys, publicKey, fingerprint: await fingerprint(publicKey) };
+    } catch (error) { if (error.name !== 'NotSupportedError') throw error; }
+  }
+  throw new Error('This browser does not support the available signing algorithms.');
+}
+export async function fingerprint(publicKey) {
+  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', fromBase64(publicKey))), b => b.toString(16).padStart(2, '0')).join('');
+}
+function input(envelope) {
+  // Sign the exact serialized payload, suite, key and protocol together.
+  return encoder.encode(JSON.stringify([DOMAIN, envelope.version, envelope.suite, envelope.publicKey, envelope.payload]));
+}
+export async function signDocument(signer, document) {
+  const envelope = { version: 1, suite: signer.suite, publicKey: signer.publicKey, payload: JSON.stringify(document) };
