+  if (doc.issuer !== 'The Daily Grind' || !['receipt', 'voucher'].includes(doc.type) || !Number.isSafeInteger(doc.amountCents) || doc.amountCents <= 0 || doc.currency !== 'USD' || typeof doc.id !== 'string' || typeof doc.customer !== 'string' || !Number.isFinite(Date.parse(doc.issuedAt))) throw new Error('The signed document contains invalid details.');
