@@ -0,0 +1,35 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { webcrypto } from 'node:crypto';
+import { generateSigner, signDocument, verifyDocument, bytesToBase64, fingerprint } from '../js/signatures.mjs';
+if (!globalThis.crypto) globalThis.crypto = webcrypto;
+const fixture = type => ({ issuer: 'The Daily Grind', type, id: 'DG-test', customer: 'Alex ☕', item: 'Maple Oat Latte', amountCents: 550, currency: 'USD', message: 'Enjoy!', issuedAt: new Date().toISOString() });
+const supportedSuites = ['Ed25519', 'ECDSA'];
+if (globalThis.SubtleCrypto?.supports?.('sign', 'ML-DSA-65')) supportedSuites.push('ML-DSA-65');
+for (const suite of supportedSuites) {
+  test(`${suite}: receipt and voucher round trip, alteration, trust and protocol checks`, async () => {
+    const keys = await crypto.subtle.generateKey(suite === 'ECDSA' ? { name: suite, namedCurve: 'P-256' } : suite, false, ['sign', 'verify']);
+    const publicKey = bytesToBase64(await crypto.subtle.exportKey('spki', keys.publicKey));
+    const signer = { keys, suite, publicKey, fingerprint: await fingerprint(publicKey) };
+    assert.equal(keys.privateKey.extractable, false);
+    await assert.rejects(crypto.subtle.exportKey('pkcs8', keys.privateKey));
+    for (const type of ['receipt', 'voucher']) {
+      const doc = fixture(type);
+      const envelope = await signDocument(signer, doc);
+      assert.deepEqual(await verifyDocument(JSON.parse(JSON.stringify(envelope)), signer), doc);
+      await assert.rejects(verifyDocument({ ...envelope, payload: envelope.payload.replace('550', '5550') }, signer), /does not match/);
+      await assert.rejects(verifyDocument(envelope, { publicKey: 'untrusted', suite }), /Unknown signer/);
+      await assert.rejects(verifyDocument(envelope, undefined), /Unknown signer/);
+      await assert.rejects(verifyDocument({ ...envelope, version: 2 }, signer), /not a supported/);
+      await assert.rejects(verifyDocument({ ...envelope, signature: 'AAAA' }, signer), /does not match/);
+      await assert.rejects(verifyDocument({ ...envelope, suite: 'RSA' }, signer), /Unsupported/);
+    }
+  });
+}
+test('automatic suite selection produces a usable non-exportable signing key', async () => {
+  const signer = await generateSigner();
+  const doc = fixture('receipt');
+  assert.deepEqual(await verifyDocument(await signDocument(signer, doc), signer), doc);
+  assert.equal(signer.fingerprint.length, 64);
+  assert.equal(signer.keys.privateKey.extractable, false);
+});

