+import { useEffect, useState } from 'react';
+import { startRegistration } from '@simplewebauthn/browser';
+import {
+  KeyIcon,
+  ShieldCheckIcon,
+  ArrowPathIcon,
+  PlusIcon,
+  PencilSquareIcon,
+  TrashIcon,
+} from '@heroicons/react/24/outline';
+import providers from '../lib/passkey-providers.json';
