+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions, generateRegistrationOptions, verifyAuthenticationResponse, verifyRegistrationResponse } from '@simplewebauthn/server';
+import { AuthError, checkPassword, digest, hashPassword, publicUser, token, transaction, type User } from '../../../lib/server/auth';
+
+export const prerender = false;
+const cookieName = 'times_session';
+const pendingCookie = 'times_ceremony';
+export const ALL: APIRoute = async ({ request, cookies, params, url }) => {
+  const json = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+  const path = import.meta.env.BASE_URL;
+  const cookieOptions = { path, httpOnly: true, sameSite: 'strict' as const, secure: url.protocol === 'https:' };
+  try {
+    if (!['GET', 'POST'].includes(request.method)) return json({ error: 'Method not allowed.' }, 405);
+    const origin = process.env.AUTH_ORIGIN || url.origin;
+    if (request.method === 'POST' && (request.headers.get('origin') !== origin || !request.headers.get('content-type')?.startsWith('application/json'))) throw new AuthError('Request origin could not be verified.', 403);
+    const body = request.method === 'POST' ? await request.json() : {};
+    return await transaction(async db => {
+      const sessionKey = digest(cookies.get(cookieName)?.value || '');
+      const session = db.sessions[sessionKey];
+      const user = session && db.users.find(u => u.id === session.userId);
+      const requireUser = () => { if (!user) throw new AuthError('Please sign in to continue.', 401); return user; };
+      const requireRecent = () => { requireUser(); if (session.verifiedAt < Date.now() - 5 * 60_000) throw new AuthError('Confirm your identity to continue.', 403, 'REAUTH_REQUIRED'); };
+      const setSession = (account: User) => { delete db.sessions[sessionKey]; const secret = token(); db.sessions[digest(secret)] = { userId: account.id, expires: Date.now() + 7 * 86400_000, verifiedAt: Date.now() }; cookies.set(cookieName, secret, { ...cookieOptions, maxAge: 7 * 86400 }); };
+      const action = params.action;
+      if (request.method === 'GET') {
+        if (action !== 'me') return json({ error: 'Not found.' }, 404);
+        return json({ user: user ? publicUser(user) : null });
+      }
+      // Bound expensive password and WebAuthn operations per browser and account.
+      let client = cookies.get('times_client')?.value;
+      if (!client) { client = token(); cookies.set('times_client', client, { ...cookieOptions, maxAge: 86400 }); }
+      const rateKeys = [digest(client), ...(typeof body.username === 'string' ? [`user:${digest(body.username.trim().toLowerCase())}`] : [])];
+      for (const rateKey of rateKeys) { const attempt = db.attempts[rateKey] ||= { count: 0, expires: Date.now() + 60_000 }; if (++attempt.count > 30) throw new AuthError('Too many attempts. Please try again in a minute.', 429); }
+      if (action === 'logout') { delete db.sessions[sessionKey]; cookies.delete(cookieName, { path }); return json({ ok: true }); }
+      if (action === 'password/signup' || action === 'password/signin') {
+        const username = typeof body.username === 'string' ? body.username.trim().toLowerCase() : '';
+        const password = typeof body.password === 'string' ? body.password : '';
+        if (!username || username.length > 120 || password.length > 256) throw new AuthError('Enter a valid username and password.');
+        let account = db.users.find(u => u.username === username);
+        if (action.endsWith('signup')) {
+          if (account) throw new AuthError('This username is already registered. Try signing in.');
+          if (password.length < 8 || !/\d/.test(password)) throw new AuthError('Use at least 8 characters and include a number.');
+          account = { id: token(), username, password: hashPassword(password), passkeys: [] }; db.users.push(account);
+        } else if (!checkPassword(password, account?.password) || !account) throw new AuthError('The username or password is incorrect.', 401);
+        setSession(account!); return json({ user: publicUser(account!) });
+      }
+      if (action === 'reauthenticate/password') {
+        requireUser();
+        if (typeof body.password !== 'string' || body.password.length > 256 || !checkPassword(body.password, user!.password)) throw new AuthError('That password is incorrect. Please try again.', 401);
+        session.verifiedAt = Date.now(); return json({ ok: true });
+      }
+      if (action === 'passkeys/options') {
+        if (body.mode === 'register') {
+          let username: string | undefined;
+          if (user) requireRecent();
+          else { username = typeof body.username === 'string' ? body.username.trim().toLowerCase() : ''; if (!username || username.length > 120) throw new AuthError('Enter a username to create your account.'); if (db.users.some(u => u.username === username)) throw new AuthError('This username is already registered. Try signing in.'); }
+          const userId = user?.id || token();
+          const options = await generateRegistrationOptions({ rpName: 'The DevTools Times', rpID: new URL(origin).hostname, userName: user?.username || username!, userID: new TextEncoder().encode(userId), attestationType: 'none', authenticatorSelection: { residentKey: 'required', userVerification: 'required' }, excludeCredentials: user?.passkeys.map(k => ({ id: k.id, transports: k.transports })) });
+          const secret = token(); db.pending[digest(secret)] = { challenge: options.challenge, kind: 'register', expires: Date.now() + 300_000, userId, username, origin, rpID: new URL(origin).hostname, sessionKey: user ? sessionKey : undefined }; cookies.set(pendingCookie, secret, { ...cookieOptions, maxAge: 300 }); return json(options);
+        }
+        const reauth = body.mode === 'reauthenticate';
+        if (reauth) requireUser();
+        const options = await generateAuthenticationOptions({ rpID: new URL(origin).hostname, userVerification: 'required', ...(reauth ? { allowCredentials: user!.passkeys.map(k => ({ id: k.id, transports: k.transports })) } : {}) });
+        if (reauth && !user!.passkeys.length) throw new AuthError('Use your password to confirm your identity.');
+        const secret = token(); db.pending[digest(secret)] = { challenge: options.challenge, kind: reauth ? 'reauthenticate' : 'authenticate', expires: Date.now() + 300_000, userId: reauth ? user!.id : undefined, sessionKey: reauth ? sessionKey : undefined, origin, rpID: new URL(origin).hostname }; cookies.set(pendingCookie, secret, { ...cookieOptions, maxAge: 300 }); return json(options);
+      }
+      if (action === 'passkeys/verify') {
+        const key = digest(cookies.get(pendingCookie)?.value || ''); const pending = db.pending[key]; delete db.pending[key]; cookies.delete(pendingCookie, { path });
+        if (!pending) throw new AuthError('This request has expired. Please try again.');
+        if (pending.sessionKey && (pending.sessionKey !== sessionKey || !user)) throw new AuthError('Your session changed. Please try again.', 401);
+        if (pending.kind === 'register') {
+          const result = await verifyRegistrationResponse({ response: body.credential, expectedChallenge: pending.challenge, expectedOrigin: pending.origin, expectedRPID: pending.rpID, requireUserVerification: true });
+          if (!result.verified) throw new AuthError('Passkey could not be verified.');
+          if (db.users.some(u => u.passkeys.some(k => k.id === result.registrationInfo.credential.id))) throw new AuthError('This passkey is already registered.');
+          let account = db.users.find(u => u.id === pending.userId);
+          if (!account) { if (!pending.username || db.users.some(u => u.username === pending.username)) throw new AuthError('This username is no longer available.'); account = { id: pending.userId!, username: pending.username, passkeys: [] }; db.users.push(account); }
+          const credential = result.registrationInfo.credential;
+          account.passkeys.push({ id: credential.id, publicKey: Buffer.from(credential.publicKey).toString('base64url'), counter: credential.counter, transports: credential.transports, name: typeof body.name === 'string' && body.name.trim() ? body.name.trim().slice(0, 60) : 'My passkey', createdAt: Date.now(), backedUp: result.registrationInfo.credentialBackedUp });
+          setSession(account); return json({ user: publicUser(account) });
+        }
+        const account = db.users.find(u => (!pending.userId || u.id === pending.userId) && u.passkeys.some(k => k.id === body.credential?.id));
+        const credential = account?.passkeys.find(k => k.id === body.credential?.id);
+        if (!account || !credential) throw new AuthError('This passkey is not associated with this account.');
+        const result = await verifyAuthenticationResponse({ response: body.credential, expectedChallenge: pending.challenge, expectedOrigin: pending.origin, expectedRPID: pending.rpID, credential: { id: credential.id, publicKey: new Uint8Array(Buffer.from(credential.publicKey, 'base64url')), counter: credential.counter, transports: credential.transports }, requireUserVerification: true });
+        if (!result.verified) throw new AuthError('Passkey could not be verified.');
+        credential.counter = result.authenticationInfo.newCounter; credential.lastUsed = Date.now(); credential.backedUp = result.authenticationInfo.credentialBackedUp;
+        if (pending.kind === 'reauthenticate') session.verifiedAt = Date.now(); else setSession(account);
+        return json({ user: publicUser(account) });
+      }
+      if (action === 'passkeys/rename' || action === 'passkeys/remove') {
+        requireRecent(); const credential = user!.passkeys.find(k => k.id === body.id); if (!credential) throw new AuthError('Passkey not found.', 404);
+        if (action.endsWith('rename')) { if (typeof body.name !== 'string' || !body.name.trim() || body.name.length > 60) throw new AuthError('Use a name between 1 and 60 characters.'); credential.name = body.name.trim(); }
+        else { if (!user!.password && user!.passkeys.length === 1) throw new AuthError('Keep at least one passkey so you can access your account.'); user!.passkeys = user!.passkeys.filter(k => k.id !== body.id); }
+        return json({ user: publicUser(user!) });
+      }
+      return json({ error: 'Not found.' }, 404);
+    });
+  } catch (error) {
+    if (error instanceof AuthError) return json({ error: error.message, code: error.code }, error.status);
+    console.error('Authentication request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return json({ error: 'We couldn’t complete that request. Please try again.' }, 400);
+  }
+};
