@@ -0,0 +1,55 @@
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { securityHeaders, publicFiles } from './security.mjs';
+
+// Deliberately no request logging, body collection, cookies, sessions, or analytics.
+const server = createServer(async (req, res) => {
+  for (const [name, value] of Object.entries(securityHeaders)) res.setHeader(name, value);
+  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
+  const finish = (status, message) => {
+    res.writeHead(status);
+    res.end(req.method === 'HEAD' ? undefined : message);
+  };
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    return finish(400, 'Invalid request.');
+  }
+
+  if (pathname === '/logout' && req.method === 'POST') {
+    // Mutations require a same-origin browser request; never use GET for clearing.
+    const origin = req.headers.origin;
+    const site = req.headers['sec-fetch-site'];
+    let sameOrigin = false;
+    try {
+      const source = new URL(origin);
+      const expectedOrigin = process.env.PUBLIC_ORIGIN || `${req.socket.encrypted ? 'https' : 'http'}://${req.headers.host}`;
+      sameOrigin = source.origin === new URL(expectedOrigin).origin;
+    } catch { /* Reject missing, opaque, or malformed origins. */ }
+    if (!sameOrigin || (site && site !== 'same-origin')) return finish(403, 'Forbidden.');
+    res.setHeader('Clear-Site-Data', '"cookies", "storage", "cache"');
+    res.setHeader('Location', '/');
+    return finish(303, 'Site data cleared where supported by your browser.');
+  }
+  if (!['GET', 'HEAD'].includes(req.method)) {
+    res.setHeader('Allow', pathname === '/logout' ? 'POST' : 'GET, HEAD');
+    return finish(405, 'Method not allowed.');
+  }
+  const file = publicFiles[pathname];
+  if (!Object.hasOwn(publicFiles, pathname)) return finish(404, 'Page not found.');
+  try {
+    const content = await readFile(new URL(file[0], import.meta.url));
+    res.setHeader('Content-Type', file[1]);
+    res.setHeader('Content-Length', content.length);
+    res.writeHead(200);
+    res.end(req.method === 'HEAD' ? undefined : content);
+  } catch {
+    // Do not expose file paths or request data in errors or logs.
+    finish(500, 'Unable to load this page.');
+  }
+});
+server.requestTimeout = 10_000;
+server.headersTimeout = 10_000;
+server.maxHeadersCount = 50;
+server.listen(Number(process.env.PORT || 11222), '0.0.0.0');

