+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { POST } from '../src/pages/api/signup.ts';
+import { CODE_LIFETIME_MS, codeDigest, createCode, matchesCode, normalizePhone, smsMessage } from '../src/utils/phone-verification.ts';
+
+const origin = 'https://news.example';
+const secret = 'test-only-secret';
+
+function fixture() {
+  const values = new Map<string, unknown>();
+  const calls: { url: string; body: string }[] = [];
+  const session = {
+    get: async (key: string) => structuredClone(values.get(key)),
+    set: async (key: string, value: unknown) => { values.set(key, structuredClone(value)); },
+    delete: async (key: string) => { values.delete(key); },
+  };
+  const request = async (body: object, requestOrigin = origin) => {
+    const response = await POST({
+      request: new Request(`${origin}/devtools-times/api/signup`, {
+        method: 'POST', headers: { Origin: requestOrigin, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
+      }), session,
+    } as unknown as Parameters<typeof POST>[0]);
+    return { status: response.status, body: await response.json() };
+  };
+  function seed(overrides = {}) {
+    values.set('phoneChallenge', {
+      phone: '+12025550123', digest: codeDigest('012345', '+12025550123', secret),
+      expiresAt: Date.now() + CODE_LIFETIME_MS, attempts: 0, ...overrides,
+    });
+  }
+  return { values, calls, request, seed };
+}
+
+const account = { action: 'register', username: 'reader', password: 'goodpassword1', code: '012345' };
+
+test('phone normalization, leading zero codes, and origin-bound SMS formatting', () => {
+  assert.equal(normalizePhone('+1 (202) 555-0123'), '+12025550123');
+  for (const phone of ['2025550123', '+0123456789', '+12025550123 ext 1', '+1', '++12025550123']) {
+    assert.equal(normalizePhone(phone), null);
+  }
+  assert.match(createCode(), /^\d{6}$/);
+  const challenge = { phone: '+12025550123', digest: codeDigest('012345', '+12025550123', secret), expiresAt: 0, attempts: 0 };
+  assert.ok(matchesCode(challenge, '012345', secret));
+  assert.ok(!matchesCode(challenge, '12345', secret));
+  assert.ok(!matchesCode(challenge, '012345', 'different secret'));
+  assert.equal(smsMessage('news.example', '012345').split('\n').at(-1), '@news.example #012345');
+});
+
+test('server verification and registration', async (t) => {
+  const savedEnv = { ...process.env };
+  const originalFetch = globalThis.fetch;
+  Object.assign(process.env, { TWILIO_ACCOUNT_SID: 'ACtest', TWILIO_AUTH_TOKEN: secret, TWILIO_FROM_NUMBER: '+12025550100', SMS_ORIGIN: origin });
+  t.after(() => { process.env = savedEnv; globalThis.fetch = originalFetch; });
+
+  await t.test('sending uses the provider without exposing the code; resends invalidate old codes and respect cooldown', async () => {
+    const f = fixture();
+    globalThis.fetch = async (input, init) => {
+      f.calls.push({ url: String(input), body: String(init?.body) });
+      return new Response('{}');
+    };
+    f.seed();
+    const sent = await f.request({ action: 'send', phone: '+1 (202) 555-0123' });
+    assert.equal(sent.status, 200);
+    assert.equal(sent.body.phone, '+12025550123');
+    assert.equal(sent.body.code, undefined);
+    const sms = new URLSearchParams(f.calls[0].body);
+    assert.equal(sms.get('To'), '+12025550123');
+    assert.match(sms.get('Body')!, /\n@news\.example #\d{6}$/);
+    assert.equal((f.values.get('phoneChallenge') as { attempts: number }).attempts, 0);
+    assert.equal((await f.request({ action: 'send', phone: '+12025550123' })).status, 429);
+    assert.equal(f.calls.length, 1);
+  });
+
+  await t.test('bad origins, missing challenges, invalid account details, expiry, and exhausted attempts never register', async () => {
+    const f = fixture();
+    globalThis.fetch = async () => { assert.fail('must not call upstream'); };
+    assert.equal((await f.request(account, 'https://attacker.example')).status, 403);
+    assert.equal((await f.request(account)).status, 400);
+    f.seed();
+    assert.equal((await f.request({ ...account, password: 'short' })).status, 400);
+    f.seed({ expiresAt: Date.now() - 1 });
+    assert.equal((await f.request(account)).body.needsNewCode, true);
+    f.seed({ attempts: 5 });
+    assert.equal((await f.request(account)).body.needsNewCode, true);
+  });
+
+  await t.test('incorrect and malformed codes count toward the five-attempt limit', async () => {
+    const f = fixture();
+    f.seed();
+    globalThis.fetch = async () => { assert.fail('must not call upstream'); };
+    for (let i = 0; i < 5; i++) {
+      const result = await f.request({ ...account, code: i === 0 ? 'bad' : '999999' });
+      assert.equal(result.status, 400);
+      assert.equal(result.body.needsNewCode, i === 4);
+    }
+    assert.equal((await f.request(account)).body.needsNewCode, true);
+  });
+
+  await t.test('successful verification forwards the server-bound phone and consumes the code', async () => {
+    const f = fixture();
+    f.seed();
+    globalThis.fetch = async (input, init) => {
+      f.calls.push({ url: String(input), body: String(init?.body) });
+      return new Response('{}');
+    };
+    assert.equal((await f.request({ ...account, phone: '+442079460000', verified: true })).status, 200);
+    assert.equal(JSON.parse(f.calls[0].body).phone, '+12025550123');
+    assert.equal(f.values.has('phoneChallenge'), false);
+    assert.equal((await f.request(account)).status, 400);
+    assert.equal(f.calls.length, 1);
+  });
+
+  await t.test('provider failure invalidates the old code and fails closed', async () => {
+    const f = fixture();
+    f.seed();
+    globalThis.fetch = async () => new Response('{}', { status: 500 });
+    assert.equal((await f.request({ action: 'send', phone: '+12025550123' })).status, 502);
+    assert.equal(f.values.has('phoneChallenge'), false);
+  });
+
+  await t.test('hourly quota and missing configuration prevent sends', async () => {
+    const f = fixture();
+    f.values.set('smsQuota', { count: 5, resetAt: Date.now() + 100000 });
+    globalThis.fetch = async () => { assert.fail('must not call provider'); };
+    assert.equal((await f.request({ action: 'send', phone: '+12025550123' })).status, 429);
+    delete process.env.TWILIO_AUTH_TOKEN;
+    assert.equal((await f.request({ action: 'send', phone: '+12025550123' })).status, 503);
+    process.env.TWILIO_AUTH_TOKEN = secret;
+  });
+
+  await t.test('upstream registration failure requires a fresh code', async () => {
+    const f = fixture();
+    f.seed();
+    globalThis.fetch = async () => new Response('{}', { status: 409 });
+    assert.equal((await f.request(account)).body.needsNewCode, true);
+    assert.equal(f.values.has('phoneChallenge'), false);
+  });
+});

