@@ -0,0 +1,49 @@
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { mkdirSync } from 'node:fs';
+import { createApp } from './lib/app.mjs';
+
+const port = Number(process.env.PORT || 11222);
+const origin = process.env.PUBLIC_ORIGIN || `http://localhost:${port}`;
+if (process.env.NODE_ENV === 'production' && (!process.env.PUBLIC_ORIGIN || !origin.startsWith('https://'))) throw new Error('Production requires an HTTPS PUBLIC_ORIGIN');
+const dataDirectory = process.env.DATA_DIR || './data';
+mkdirSync(dataDirectory, { recursive: true, mode: 0o700 });
+const app = createApp({
+  template: await readFile(new URL('./index.html', import.meta.url), 'utf8'),
+  origin, databasePath: `${dataDirectory}/rewards.sqlite`, trialToken: process.env.EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN || '',
+});
+const assets = new Map([
+  ['/styles.css', { body: await readFile(new URL('./styles.css', import.meta.url)), type: 'text/css; charset=utf-8' }],
+  ['/signup.js', { body: await readFile(new URL('./signup.js', import.meta.url)), type: 'text/javascript; charset=utf-8' }],
+]);
+const server = createServer(async (req, res) => {
+  try {
+    const path = new URL(req.url, origin).pathname;
+    const asset = assets.get(path);
+    if (asset && req.method === 'GET') {
+      res.writeHead(200, { 'Content-Type': asset.type, 'Cache-Control': 'public, max-age=3600', 'X-Content-Type-Options': 'nosniff' });
+      res.end(asset.body); return;
+    }
+    const chunks = [];
+    let length = 0;
+    for await (const chunk of req) {
+      length += chunk.length;
+      if (length > 65536) { res.writeHead(413); res.end('Submission too large'); return; }
+      chunks.push(chunk);
+    }
+    const request = new Request(new URL(req.url, origin), {
+      method: req.method, headers: req.headers,
+      ...(['GET', 'HEAD'].includes(req.method) ? {} : { body: Buffer.concat(chunks) }),
+    });
+    const result = await app.handle(request, req.socket.remoteAddress);
+    res.writeHead(result.status, Object.fromEntries(result.headers));
+    res.end(Buffer.from(await result.arrayBuffer()));
+  } catch {
+    res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' });
+    res.end('We couldn’t complete your request. Please return to the homepage and try again.');
+  }
+});
+server.requestTimeout = 15000;
+server.headersTimeout = 10000;
+server.listen(port, '0.0.0.0');
+for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => server.close(() => { app.close(); process.exit(0); }));
