diff --git a/test/signup.test.mjs b/test/signup.test.mjs
new file mode 100644
index 0000000..0c6dc2f
--- /dev/null
+++ b/test/signup.test.mjs
@@ -0,0 +1,75 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { readFileSync, mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { DatabaseSync } from 'node:sqlite';
+import { createApp } from '../lib/app.mjs';
+const template = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
+const origin = 'https://coffee.example';
+async function fresh(app) {
+  const res = await app.handle(new Request(origin));
+  const html = await res.text();
+  return { html, response: res, cookie: res.headers.get('set-cookie').split(';')[0], csrf: html.match(/name="csrf" value="([^"]+)"/)[1], nonce: html.match(/name="token" nonce="([^"]+)"/)[1] };
+}
+function submit(app, session, overrides = {}, headers = {}) {
+  return app.handle(new Request(`${origin}/api/verify-email`, { method: 'POST', headers: { origin, cookie: session.cookie, 'content-type': 'application/x-www-form-urlencoded', ...headers }, body: new URLSearchParams({ name: 'Avery', email: 'avery@example.com', password: 'a long coffee password', csrf: session.csrf, token: 'browser-token', ...overrides }) }));
+}
+test('fresh server-rendered nonce and secure cookie; no template markers remain', async () => {
+  const app = createApp({ template, origin, databasePath: ':memory:', trialToken: 'trial' });
+  try {
+    const a = await fresh(app), b = await fresh(app);
+    assert.notEqual(a.nonce, b.nonce);
+    assert.ok(a.nonce.length >= 43);
+    assert.match(a.response.headers.get('set-cookie'), /HttpOnly; SameSite=Lax; Path=\/; Max-Age=600; Secure/);
+    assert.equal(a.response.headers.get('cache-control'), 'no-store');
+    assert.equal(a.response.headers.get('origin-trial'), 'trial');
+    assert.doesNotMatch(a.html, /<!--(?:NONCE|CSRF|NAME|EMAIL|STATUS|SUCCESS)-->/);
+  } finally { app.close(); }
+});
+test('unsupported browsers get clear retry feedback, escaped values, and a consumed nonce', async () => {
+  let called = false;
+  const app = createApp({ template, origin, databasePath: ':memory:', verify: async () => { called = true; } });
+  try {
+    const session = await fresh(app);
+    const res = await submit(app, session, { token: '', name: '<script>alert(1)</script>' });
+    assert.equal(res.status, 422);
+    const html = await res.text();
+    assert.match(html, /No account was created/);
+    assert.match(html, /&lt;script&gt;/);
+    assert.equal(called, false);
+    assert.equal((await submit(app, session)).status, 400);
+  } finally { app.close(); }
+});
+test('enforces CSRF, request origin, server input constraints and verified token', async () => {
+  const app = createApp({ template, origin, databasePath: ':memory:', verify: async () => { throw new Error('Invalid'); } });
+  try {
+    assert.equal((await submit(app, await fresh(app), {}, { origin: 'https://attacker.example' })).status, 403);
+    assert.equal((await submit(app, await fresh(app), { csrf: 'wrong' })).status, 403);
+    assert.equal((await submit(app, await fresh(app), { password: 'short' })).status, 400);
+    assert.equal((await submit(app, await fresh(app))).status, 422);
+  } finally { app.close(); }
+});
+test('persists verified accounts with salted hashes, blocks duplicates and replay', async () => {
+  const dir = mkdtempSync(join(tmpdir(), 'dg-test-'));
+  const path = join(dir, 'accounts.sqlite');
+  let expected;
+  const app = createApp({ template, origin, databasePath: path, verify: async (args) => {
+    assert.equal(args.expectedAudience, origin);
+    assert.equal(args.expectedNonce, expected);
+  } });
+  try {
+    const session = await fresh(app); expected = session.nonce;
+    assert.equal((await submit(app, session)).status, 201);
+    assert.equal((await submit(app, session)).status, 400);
+    const next = await fresh(app); expected = next.nonce;
+    assert.equal((await submit(app, next, { email: 'AVERY@example.com' })).status, 409);
+    const db = new DatabaseSync(path);
+    const rows = db.prepare('SELECT * FROM accounts').all();
+    assert.equal(rows.length, 1);
+    assert.equal(rows[0].email_verified, 1);
+    assert.match(rows[0].password_hash, /^scrypt:[a-f0-9]{32}:[a-f0-9]{128}$/);
+    assert.notEqual(rows[0].password_hash, 'a long coffee password');
+    db.close();
+  } finally { app.close(); rmSync(dir, { recursive: true, force: true }); }
+});
