+        if (!open) return;
+        const rect = trigger.getBoundingClientRect();
+        const viewport = window.visualViewport;
+        const leftEdge = (viewport?.offsetLeft ?? 0) + 8;
+        const topEdge = (viewport?.offsetTop ?? 0) + 8;
+        const rightEdge = leftEdge + (viewport?.width ?? innerWidth) - 16;
+        const bottomEdge = topEdge + (viewport?.height ?? innerHeight) - 16;
+        panel.style.maxWidth = `${Math.max(0, rightEdge - leftEdge)}px`;
+        panel.style.maxHeight = `${Math.max(0, bottomEdge - topEdge)}px`;
+        const { width, height } = panel.getBoundingClientRect();
+        const below = Math.max(0, bottomEdge - rect.bottom);
+        const above = Math.max(0, rect.top - topEdge);
+        const flipUp = height > below && above > below;
+        panel.style.maxHeight = `${flipUp ? above : below}px`;
+        const left = rect.left + width > rightEdge ? rect.right - width : rect.left;
+        const top = flipUp ? rect.top - Math.min(height, above) : rect.bottom;
+        Object.assign(panel.style, {
+          inset: 'auto', margin: '0',
+          left: `${Math.max(leftEdge, Math.min(left, rightEdge - width))}px`,
+          top: `${Math.max(topEdge, Math.min(top, bottomEdge))}px`,
+        });
+      };
+      panel.addEventListener('toggle', (event) => {
+        open = event.newState === 'open';
+        placePanel();
+      });
+      window.addEventListener('resize', placePanel);
+      document.addEventListener('scroll', placePanel, true);
+      window.visualViewport?.addEventListener('resize', placePanel);
+      window.visualViewport?.addEventListener('scroll', placePanel);
+      new ResizeObserver(placePanel).observe(trigger);
+    }
+  </script>
